/** Checks every pasted line before any is added: the user pasting must be one the sheet permits to open (see
 *  SettingRepository#permits), its person must be on the sheet (names compared as names are, case and outer spaces
 *  ignored), its reference not repeating one on an earlier line (case ignored). A line whose person, date and note
 *  match claims of that person as they stood before the paste (not VOID nor DELETED) updates the newest such DRAFT
 *  (one an earlier line of the paste has not taken) to the line's amount, which must keep the rules of editing a claim (see ApplyClaim);
 *  a line whose matches include no such DRAFT fails. Any other line must keep the rules of adding a claim (see
 *  ClaimRules). Any failing line refuses the whole paste. */
public class CheckPastedClaims {
    public void check(@PathVariable("sheetId") String sheetId, @Val PastedLines pasted, PersonRepository people,
            SettingRepository settings, PeriodRepository periods, ClaimRepository claims, HolidayRepository holidays,
            RoleRepository roles, Out<PastedClaims> checked)
            throws InvalidClaimException {
        String sheet = sheetId.trim();
        String role = roles.roleOf(sheet, pasted.by());
        if (!settings.permits(sheet, "open", role)) {
            throw new InvalidClaimException("A " + role + " may not open a claim");
        }
        List<Claim> stood = claims.list(sheet);
        Set<Long> taken = new HashSet<>();
        List<PastedClaim> all = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (PastedLine line : pasted.lines()) {
            Person person = people.findByName(sheet, line.name());
            if (person == null) {
                throw new InvalidClaimException("No person named " + line.name() + " on the sheet");
            }
            String ref = line.values().ref();
            if (ref != null && !refs.add(ClaimValues.refKey(ref))) {
                throw new InvalidClaimException("The reference " + ref + " is pasted more than once");
            }
            LocalDate date = line.values().date() != null ? line.values().date() : settings.claimDate(sheet);
            String note = noteOf(line.values().note());
            List<Claim> matches = stood.stream()
                    .filter((c) -> c.personId() == person.id() && date.equals(c.date())
                            && note.equals(noteOf(c.note())) && c.status() != ClaimStatus.VOID
                            && c.status() != ClaimStatus.DELETED)
                    .toList();
            if (matches.isEmpty()) {
                all.add(new PastedClaim(person, line.values(),
                        ClaimRules.check(person, line.values(), settings, periods, claims, holidays), null));
                continue;
            }
            Claim draft = matches.stream()
                    .filter((c) -> c.status() == ClaimStatus.DRAFT && !taken.contains(c.id()))
                    .max(Comparator.comparingLong(Claim::id)).orElse(null);
            if (draft == null) {
                throw new InvalidClaimException("The line for " + line.name() + " matches no DRAFT claim to update");
            }
            taken.add(draft.id());
            if (periods.closedOn(sheet, draft.dueBy())) {
                throw new InvalidClaimException("The claim's due-by is inside a closed period");
            }
            if (!person.mayClaimOn(date)) {
                throw new InvalidClaimException("The claim's date is after the person's retirement date");
            }
            if (line.values().amount().compareTo(draft.amount()) != 0 && claims.hasLines(sheet, draft.id())) {
                throw new InvalidClaimException("A claim with lines takes its amount from them");
            }
            all.add(new PastedClaim(person, line.values(),
                    new ClaimRules.Checked(date, draft.corrects(), draft.dueBy(), 0), draft));
        }
        checked.set(new PastedClaims(all));
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Takes the checked lines in the order pasted. A line that adds a claim adds it as a DRAFT as AddClaim adds one,
 *  writing CLAIM_ADDED (with ref=<reference> at its end when it has one; and LATE_ENTRY after it for a late entry); a
 *  line that updates a DRAFT edits it to the line's amount as the claim's editor would, writing CLAIM_EDITED when the
 *  amount changes. Either claim is then opened by the user pasting as the open button opens it (see ApplyClaimStatus,
 *  SaveClaimStatus): one with an empty note whose due is above the note threshold, or one that would take its person
 *  past its period's cap (those opened before it in the paste count), refuses the whole paste. It takes its number,
 *  writes CLAIM_OPENED and the figures the line moved (see Rollup). No line is written to the audit file until every
 *  line has gone through; a refusal writes nothing (the transaction gives back what was stored). */
public class AddPastedClaims {
    public void add(@PathVariable("sheetId") String sheetId, @Val PastedClaims checked, @Val PastedLines pasted,
            ClaimRepository claims, PersonRepository people, RateRepository rates, SettingRepository settings,
            PeriodRepository periods, SheetRepository sheets, ClaimLog log, Rollup rollup, Audit audit,
            Out<PasteClaimsResult> result) throws InvalidClaimException {
        String sheet = sheetId.trim();
        String by = pasted.by();
        List<String> lines = new ArrayList<>();
        for (PastedClaim c : checked.claims()) {
            RollupBefore before = rollup.take(sheet);
            String person = c.person().name();
            Claim claim;
            if (c.draft() == null) {
                LocalDate date = c.checked().date();
                claim = claims.add(sheet, c.person().id(), c.values().amount(), date, c.values().note(),
                        c.checked().corrects(), c.values().ref(), c.values().tags(), c.checked().dueBy(), c.checked().terms());
                log.write(claim, by);
                lines.add("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + by + " person=" + person
                        + " amount=" + claim.amount().toPlainString() + " date=" + claim.date()
                        + (claim.ref() == null ? "" : " ref=" + claim.ref()));
                if (periods.softClosedOn(sheet, c.checked().dueBy())) {
                    claims.markLateEntry(claim);
                    lines.add("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + by + " person=" + person
                            + " amount=" + claim.amount().toPlainString() + " date=" + claim.date());
                }
            } else {
                Claim draft = c.draft();
                claim = draft;
                if (c.values().amount().compareTo(draft.amount()) != 0) {
                    claim = new Claim(draft.id(), draft.sheetId(), draft.personId(), c.values().amount(), draft.date(),
                            draft.note(), draft.status(), draft.number(), draft.due(), draft.openedBy(), draft.stated(),
                            draft.statedDue(), draft.corrects(), draft.dueBy(), draft.deferredUntil(), draft.proofs(),
                            draft.splitFrom(), draft.ref(), draft.tags());
                    if (!claims.update(claim, by, sheets.today(sheet))) {
                        throw new InvalidClaimException("Only a DRAFT claim no one else is editing can be edited");
                    }
                    lines.add("CLAIM_EDITED sheet=" + sheet + " by=" + by + " person=" + person
                            + " amount=" + claim.amount().toPlainString() + " date=" + claim.date());
                }
                claim = claims.find(sheet, claim.id());
            }
            if (ApplyClaimStatus.needsNote(claim, people, rates, settings, LateCharge.of(sheet, sheets, settings, claims))) {
                throw new InvalidClaimException("A claim whose due is above the note threshold needs a note to be opened");
            }
            if (ClaimRules.overCap(claim, periods, claims)) {
                throw new InvalidClaimException("The person already has as many open claims in the period as its cap allows");
            }
            String number = ClaimNumbering.next(claim, claims, periods, settings, sheets);
            Claim opened = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), ClaimStatus.OPEN, number, claim.due(), by, claim.stated(), claim.statedDue(),
                    claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(),
                    claim.ref(), claim.tags());
            if (!claims.updateStatus(opened, ClaimStatus.DRAFT)) {
                throw new InvalidClaimException("The claim was changed by someone else");
            }
            log.write(opened, by);
            lines.add("CLAIM_OPENED sheet=" + sheet + " by=" + by + " person=" + person + " amount="
                    + opened.amount().toPlainString() + " date=" + opened.date() + " number=" + number);
            lines.addAll(rollup.lines(sheet, by, before));
        }
        lines.forEach(audit::record);
        result.set(new PasteClaimsResult(checked.claims().size()));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
public final class ClaimRules {

    private ClaimRules() {
    }

    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
     *  correct a SETTLED claim (see Corrections), or a reference already used on the sheet (see checkRef). */
    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
        int terms = terms(person, date, settings);
        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
        if (periods.closedOn(person.sheetId(), dueBy)) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        if (!person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        checkRef(person.sheetId(), values, null, claims);
        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy, terms);
    }

    /** Refuses a reference another claim of the sheet already has, comparing without regard to case; {@code self} is the
     *  claim being edited (null for an add), whose own reference does not count. */
    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
        }
    }

    /** The due-by a claim of the person dated the date is fixed with as it is added: the terms-th business day after its date (see
     *  HolidayRepository.businessDaysAfter), the terms being the person's own in force on that date, else those of their grade in force on it (the
     *  holidays on the sheet now decide; one added later works it out again, see ClaimRepository#refixDueBys). */
    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.businessDaysAfter(person.sheetId(), date, terms(person, date, settings));
    }

    /** The terms a claim of the person dated the date is fixed with: the person's own in force on that date, else those of their grade in force on
     *  that date. The claim keeps them, so its due-by can be worked out again when a holiday is added (see ClaimRepository#refixDueBys). */
    public static int terms(Person person, LocalDate date, SettingRepository settings) {
        return settings.terms(person.sheetId(), person.termsOn(date), person.gradeOn(date), date);
    }

    /** Whether opening the claim would take its person past the cap of the period its due-by falls in: they already have
     *  that many OPEN or PENDING claims in it (a period with no cap, or no period: never). */
    public static boolean overCap(Claim claim, PeriodRepository periods, ClaimRepository claims) {
        Period period = periods.containing(claim.sheetId(), claim.dueBy());
        return period != null && period.cap() != null
                && claims.heldIn(claim.sheetId(), claim.personId(), period.from(), period.to()) >= period.cap();
    }

    /** A claim's date, the number it corrects (null when none), its due-by and the terms it was fixed with, once its rules are kept. */
    public record Checked(LocalDate date, String corrects, LocalDate dueBy, int terms) {
    }
}

