package net.officefloor.hq.app.person;

/** Body of an add or edit of a person, and who makes it. An edit carries the version of the person it was made from,
 *  and the date (yyyy-MM-dd) its grade is from: blank for the sheet's today. {@code terms} are the person's own terms in
 *  days, blank for none. {@code contact}
 *  is the person's contact, blank for none. {@code tags} are the person's tags, comma separated (null or blank: none).
 *  {@code termsFrom} is the date (yyyy-MM-dd) the terms are from: blank (or null) for the beginning of time. */
public record PersonRequest(String name, String grade, String by, Long version, String gradeFrom, String terms, String contact,
        String tags, String termsFrom) {

    public PersonRequest(String name, String grade, String by, Long version, String gradeFrom, String terms, String contact,
            String tags) {
        this(name, grade, by, version, gradeFrom, terms, contact, tags, null);
    }
}
3:import { HttpError, postJson, putJson } from '../../api/http';
44:      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add`, { ...v, by: user }),
112:      return id === undefined ? postJson<Person>(base, body) : putJson<Person>(`${base}/${id}`, body);

    /** Stores the person as its new version, with its grades, only while the stored one is still {@code fromVersion}:
     *  a save that lands in between refuses this one. */
    public void update(Person person, long fromVersion)
            throws DuplicatePersonNameException, DuplicatePersonContactException, StalePersonException {
        List<Integer> termsWas = jdbc.query("SELECT terms FROM person WHERE sheet_id = ? AND id = ?",
                (rs, n) -> rs.getObject(1, Integer.class), person.sheetId(), person.id());
        int n;
        try {
            n = jdbc.update("UPDATE person SET name = ?, version = ?, terms = ?, contact = ?, tags = ? WHERE sheet_id = ? AND id = ? AND version = ?",
                    person.name(), person.version(), person.baseTerms(), person.contact(), stored(person.tags()), person.sheetId(), person.id(), fromVersion);
        } catch (DuplicateKeyException e) {
            if (contactClash(e)) {
                throw new DuplicatePersonContactException(person.contact());
            }
            throw new DuplicatePersonNameException(person.name());
        }
        if (n == 0) {
            throw new StalePersonException(person.id());
        }
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", person.sheetId(), person.id());
        for (PersonGrade g : person.grades()) {
            jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
                    person.sheetId(), person.id(), g.from() == null ? null : Date.valueOf(g.from()), g.grade());
        }
        logGrades(person.sheetId(), person.id(), person.grades());
        Integer was = termsWas.isEmpty() ? null : termsWas.get(0);
        if (!java.util.Objects.equals(was, person.baseTerms())) {
            jdbc.update("INSERT INTO person_terms_log (sheet_id, person_id, terms_was, terms, made_on) VALUES (?, ?, ?, ?, ?)",
                    person.sheetId(), person.id(), was, person.baseTerms(), Date.valueOf(sheets.today(person.sheetId())));
        }
        jdbc.update("DELETE FROM person_terms_from WHERE sheet_id = ? AND person_id = ?", person.sheetId(), person.id());
        for (PersonTerms t : person.ownTerms()) {
            if (t.from() != null) {
                recordTerms(person.sheetId(), person.id(), t);
            }
        }
    }

#!/usr/bin/env bash
# Start the Spring Boot app on $PORT (main class net.officefloor.hq.app.Application). On boot, Flyway
# migrates the empty in-memory H2 up to the current schema; Spring serves the SPA (static/) and the
# app's REST endpoints. Returns once
# launching; poll /actuator/health for readiness.
set -euo pipefail
cd "$(dirname "$0")/.."
mkdir -p .run

: "${PORT:?PORT must be set}"
JAR="$(ls -t target/*.jar 2>/dev/null | head -n1 || true)"
[ -n "$JAR" ] || { echo "no jar in target/ — run bin/build first" >&2; exit 1; }

# Known audit file (the file-based test-assertion channel). Absolute so app + tests agree.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

nohup java -jar "$JAR" --server.port="$PORT" --spring.profiles.active=e2e > .run/app.log 2>&1 &
echo $! > .run/app.pid

